def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_defects = sum(1 for o in opp if o == 'D')
    my_defects = sum(1 for m in my if m == 'D')

    if opp_defects > n * 0.5:
        return 'D'

    ret_total = 0
    ret_count = 0
    for i in range(n - 1):
        if my[i] == 'D':
            ret_total += 1
            if opp[i + 1] == 'D':
                ret_count += 1
    ret_rate = ret_count / ret_total if ret_total > 0 else 0.0

    retaliator = False
    if ret_total >= 1 and ret_rate > 0.5:
        retaliator = True
    if ret_total >= 2 and ret_rate > 0.3:
        retaliator = True

    if retaliator:
        if n >= 98:
            return 'C' if n == 98 else 'D'
        last_my, last_opp = history[-1]
        if last_opp == 'D':
            provoked = False
            if last_my == 'D':
                provoked = True
            elif n >= 2 and history[-2][0] == 'D':
                provoked = True
            if provoked:
                return 'C'
            else:
                return 'D'
        return 'C'

    else:
        if n >= 98:
            return 'D'
        last_my, last_opp = history[-1]
        if last_opp == 'D':
            return 'C'
        if my_defects == 0 and n == 10:
            return 'D'
        if my_defects == 1 and n == 11:
            return 'C'
        if ret_total > 0 and ret_rate <= 0.3:
            return 'D'
        return 'C'
